export function ErrorNetworkRetryVisual(props: ErrorStateVisualBaseProps) {
  const reactId = useId();
  const idPrefix = `error-network-retry-${reactId.replaceAll(":", "")}`;

  return (
    <ErrorStateSvg viewBox="209 160 1629 1634" {...props}>
      <defs>
        <ErrorStateLayerMasks
          cutoutPaths={cutoutPaths}
          idPrefix={idPrefix}
          visiblePaths={visiblePaths}
        />
      </defs>
      <ErrorStateLayeredPaths
        cutoutPaths={cutoutPaths}
        idPrefix={idPrefix}
        visiblePaths={visiblePaths}
      />
    </ErrorStateSvg>
  );
}
